def esc(value: object) -> str:
    return html.escape(str(value), quote=True)


def page(title: str, body: str) -> str:
    return ("<!doctype html><html lang='en'><head><meta charset='utf-8'>"
            "<meta name='viewport' content='width=device-width,initial-scale=1'>"
            f"<title>{esc(title)}</title><style>{CSS}</style>"
            "<script defer src='https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js'></script>"
            f"</head><body><header><div><h1>{esc(title)}</h1><p>ASTR 476: Observational Cosmology · {TODAY}</p></div></header><main>{body}</main></body></html>")


def list_html(items: list[str], tag: str = "ul") -> str:
    return f"<{tag}>" + "".join(f"<li>{esc(item)}</li>" for item in items) + f"</{tag}>"


def axes(xlabel: str, ylabel: str) -> str:
    return ("<path d='M75 320H720M75 320V38' fill='none' stroke='#263746' stroke-width='2'/>"
            f"<text x='395' y='365' text-anchor='middle'>{esc(xlabel)}</text>"
            f"<text x='20' y='180' transform='rotate(-90 20 180)' text-anchor='middle'>{esc(ylabel)}</text>")


