def fit_excerpt_intercept() -> dict[str, float]:
    with SUBSET.open(encoding="utf-8", newline="") as stream:
        rows = list(csv.DictReader(stream))
    covariance = np.loadtxt(SUBSET_COV, delimiter=",")
    if covariance.shape != (len(rows), len(rows)):
        raise ValueError("Pantheon+ excerpt and covariance dimensions disagree")
    residual = np.array([float(row["MU_SH0ES"]) - distance_modulus(float(row["zHD"])) for row in rows])
    ones = np.ones(len(rows))
    inv_ones = np.linalg.solve(covariance, ones)
    inv_residual = np.linalg.solve(covariance, residual)
    beta = float(ones @ inv_residual / (ones @ inv_ones))
    sigma = float(1.0 / math.sqrt(ones @ inv_ones))
    adjusted = residual - beta
    return {"objects": float(len(rows)), "intercept_mag": beta, "intercept_sigma_mag": sigma,
            "chi2_fixed_intercept": gaussian_chi_square(residual, covariance),
            "chi2_fitted_intercept": gaussian_chi_square(adjusted, covariance)}


def growth_factor(z: float) -> float:
    from scipy.integrate import quad
    a = 1.0 / (1.0 + z)
    def e_of_a(value: float) -> float:
        return math.sqrt(OMEGA_M / value**3 + 1.0 - OMEGA_M)
    integral, _ = quad(lambda value: 1.0 / (value**3 * e_of_a(value)**3), 1e-7, a)
    present_integral, _ = quad(lambda value: 1.0 / (value**3 * e_of_a(value)**3), 1e-7, 1.0)
    return (e_of_a(a) * integral) / (e_of_a(1.0) * present_integral)


def growth_rate(z: float, step: float) -> float:
    a = 1.0 / (1.0 + z)
    z_high_a = 1.0 / (a * math.exp(step)) - 1.0
    z_low_a = 1.0 / (a * math.exp(-step)) - 1.0
    return (math.log(growth_factor(z_high_a)) - math.log(growth_factor(z_low_a))) / (2.0 * step)


def assessment_results() -> dict[str, object]:
    intercept = fit_excerpt_intercept()
    bao = [item for item in PUBLISHED_SUMMARIES if item["observable"] == "D_V_times_rd_fid_over_rd"]
    return {
        "hubble_distance_mpc": 299_792.458 / H0_KM_S_MPC,
        "hubble_time_gyr": 1.0 / (H0_KM_S_MPC / 3.085677581491367e19) / (365.25*86400*1e9),
        "mu_z_0_1": distance_modulus(0.1), "mu_z_0_5": distance_modulus(0.5),
        "mu_z_1": distance_modulus(1.0),
        "distance_grid": {str(z): {"dc": comoving_distance_mpc(z), "dl": luminosity_distance_mpc(z),
                        "da": luminosity_distance_mpc(z)/(1+z)**2,
                        "mu": distance_modulus(z)} for z in (0.5, 1.0)},
        "bao": [{"z": float(item["redshift"]), "observed": float(item["value"]),
                 "sigma": float(item["upper_error"]), "model_dv": volume_averaged_distance_mpc(float(item["redshift"]))}
                for item in bao],
        "theta_deg": angular_scale_degrees(),
        "theta_arcmin": angular_scale_degrees()*60,
        "theta_sigma_deg": 0.0003/100*180/math.pi,
        "theta_sigma_rad": 0.0003/100,
        "theta_sigma_arcmin": 0.0003/100*180/math.pi*60,
        "des_sigma8_conditional": 0.776*math.sqrt(0.3/0.339),
        "des_sigma8_at_omega_lower": 0.776*math.sqrt(0.3/(0.339-0.031)),
        "des_sigma8_at_omega_upper": 0.776*math.sqrt(0.3/(0.339+0.032)),
        "growth": {str(z): growth_factor(z) for z in (0.0, 0.5, 1.0)},
        "growth_rate_z0_5_h001": growth_rate(0.5, 0.01),
        "growth_rate_z0_5_h0005": growth_rate(0.5, 0.005),
        "pantheon_excerpt_gls": intercept,
    }


