def question_sets(results: dict[str, object]) -> list[dict[str, object]]:
    return [
        {"title":"Redshift and expansion scales","scope":"Lectures 01-02","questions":["A spectral line has rest wavelength 500.0 nm and is observed at 510.0 nm. Calculate z and state what additional assumption is required before treating cz as a recession speed.","Using the course fiducial H0, calculate c/H0 in Mpc and the Hubble time in Gyr. Explain why the Hubble time is not automatically the age of the Universe.","Starting from the distance-modulus definition, derive the low-z approximation mu=5 log10(cz/H0)+25 when D_L is expressed in Mpc. State where the approximation fails.","A nearby galaxy has a 300 km/s peculiar velocity. At what redshift is cz equal to 300 km/s? Explain why this sets a practical scale for peculiar-velocity importance."]},
        {"title":"Distance measures and standard candles","scope":"Lectures 03-04","questions":["At z=0.5 and z=1, calculate D_C, D_L, D_A, and mu using the supplied flat-LCDM integrator. Show the reciprocity check.","For z=1, compare the computed mu to a hypothetical standardized observation 0.20 mag brighter. Estimate the fractional distance change using a first-order expansion and state its sign.","Explain why changing H0 shifts the Hubble diagram's intercept while relative shape can still constrain expansion history.","For an 18-row covariance-aware demonstration, list the dimensions and meaning of the covariance matrix. Explain why it is invalid to infer a Pantheon+ cosmological constraint from the excerpt."]},
        {"title":"BAO and the sound horizon","scope":"Lectures 05-06","questions":["Compute D_V at z=0.38, 0.51, and 0.61. Show D_M and c/H(z) before taking the cube root.","At z=0.38, compare your model distance to the BOSS published summary only after stating r_d=r_d,fid. Calculate the one-point standardized residual.","If the true sound horizon is 2% smaller than the fiducial ruler, state how the reported D_V r_d,fid/r_d scale changes relative to D_V. Keep the convention algebra explicit.","Explain one advantage and one information loss of isotropic D_V compared with separate D_M/r_d and H(z)r_d constraints."]},
        {"title":"CMB acoustic-scale inference","scope":"Lectures 07-08","questions":["Convert Planck's 100 theta-star=1.0411±0.0003 to theta-star in radians, degrees, and arcminutes. Propagate the quoted error.","Derive theta-star=r_s(z*)/D_M(z*) and identify which factors are mainly early-universe and late-universe dependent.","A student calls the lecture's oscillatory C_ell sketch 'the Planck spectrum.' Identify the evidentiary error and rewrite the caption accurately.","Explain why a precise acoustic angle does not determine H0 without assumptions about sound-horizon physics, curvature, and the expansion model."]},
        {"title":"Weak-lensing parameter combinations","scope":"Lectures 09-10","questions":["Invert S8=sigma8 sqrt(Omega_m/0.3) using the DES Y3 central S8 and Omega_m values. Report the result as conditional on the central Omega_m.","Holding S8 fixed, calculate the sigma8 values at the lower and upper quoted Omega_m endpoints. Explain why this range is not a propagated confidence interval.","List the three two-point function families in a 3x2pt analysis and give one distinct systematic for each or for their shared calibration.","Explain why S8 is a compressed parameter combination rather than a direct measurement of sigma8 alone."]},
        {"title":"Growth and parameter inference","scope":"Lectures 11-12","questions":["Report the normalized model growth factor at z=0, 0.5, and 1 from the supplied script. Describe the normalization and two omitted physical effects.","Estimate f=d ln D/d ln a at z=0.5 with centered finite differences using h=0.01 and h=0.005. Compare the results and state a convergence criterion.","For a Gaussian residual vector, derive the Cholesky-whitened expression for chi-square and explain why explicit matrix inversion is discouraged.","Distinguish a likelihood contour from a marginalized posterior contour. Name one way a prior can affect the latter."]},
        {"title":"Evidence audit and synthesis","scope":"Lectures 13-14","questions":["Using the included Pantheon+ subset, fit only a constant intercept at fixed fiducial distance-redshift shape with the full covariance. Report beta, its GLS standard error, and chi-square before/after fitting.","State why the fitted intercept is conditional on this teaching subset and does not estimate Omega_m or reproduce a published H0 constraint.","Choose one Planck, BOSS, Pantheon+, or DES summary row. Write its probe, observable, model assumptions, uncertainty convention, source key, and provenance level.","A collaborator proposes combining all four probes by adding inverse variances. Identify at least four missing ingredients required before that joint inference is defensible."]},
    ]


def write_problem_sets(results: dict[str, object]) -> None:
    sets = question_sets(results)
    solved = [
        [f"z=(510.0/500.0)-1=0.0200. The Doppler-only interpretation is only an approximation; cosmological expansion, peculiar motion, and line identification must be addressed.",f"c/H0={results['hubble_distance_mpc']:.3f} Mpc; 1/H0={results['hubble_time_gyr']:.4f} Gyr. Age requires integrating the expansion history and assumptions about contents/curvature.","At low z, D_L approximately cz/H0; substitute in mu=5 log10(D_L/Mpc)+25. It fails when higher-order expansion terms and peculiar velocities matter.","z=300/299792.458={300/299792.458:.6f}. At comparable cz, peculiar velocities are not a small correction."],
        ["; ".join(f"z={z}: D_C={row['dc']:.3f} Mpc, D_L={row['dl']:.3f} Mpc, D_A={row['da']:.3f} Mpc, mu={row['mu']:.4f} mag" for z,row in results["distance_grid"].items())+"; reciprocity is satisfied by construction.",f"A -0.20 mag residual implies fractional distance change approximately (ln10/5)(-0.20)={math.log(10)/5*(-0.2):.4f}, about {100*math.log(10)/5*(-0.2):.2f}% in the linear approximation; brighter means smaller inferred distance at fixed standard candle.","H0 rescales distances at every redshift and is degenerate with absolute magnitude/calibration in an unanchored SN Hubble diagram; relative redshift curvature carries shape information.","The selected data and covariance are both 18-dimensional and row aligned. Redshift stratification, small size, and absent full likelihood prevent survey-level inference."],
        [*[f"z={item['z']:.2f}: D_V(model)={item['model_dv']:.3f} Mpc." for item in results["bao"]],f"At z=0.38, residual=({results['bao'][0]['model_dv']:.3f}-{results['bao'][0]['observed']:.1f})/{results['bao'][0]['sigma']:.1f}={((results['bao'][0]['model_dv']-results['bao'][0]['observed'])/results['bao'][0]['sigma']):.3f}; conditional on r_d=r_d,fid and not a full likelihood.","D_V^scaled=D_V r_d,fid/r_d. If r_d is 0.98 r_d,fid, the scale is D_V/0.98, 1.0204 D_V, about 2.04% larger.","Isotropic compression improves signal-to-noise for an averaged scale but discards separate radial/transverse geometric information."],
        [f"theta={results['theta_deg']:.6f} deg = {results['theta_arcmin']:.4f} arcmin = {math.radians(results['theta_deg']):.8f} rad; sigma_theta={results['theta_sigma_rad']:.8f} rad = {results['theta_sigma_deg']:.8f} deg = {results['theta_sigma_arcmin']:.6f} arcmin.","The sound horizon is set by pre-recombination baryon-photon physics; D_M(z*) integrates the expansion and depends on late geometry as well as curvature/model assumptions.","The curve is a theoretical illustrative acoustic oscillation, not fetched Planck bandpowers; caption it as a schematic with no observational points or likelihood.","H0 inference requires a calibrated r_s and assumptions about early expansion, curvature, and late-time model; the angle alone is a ratio."],
        [f"sigma8=0.776 sqrt(0.3/0.339)={results['des_sigma8_conditional']:.5f}, conditional on central Omega_m.",f"Endpoint transformations at fixed S8: {results['des_sigma8_at_omega_lower']:.5f} for Omega_m lower and {results['des_sigma8_at_omega_upper']:.5f} for Omega_m upper. They ignore covariance and variation in S8.","Cosmic shear, galaxy-galaxy lensing, and galaxy clustering; examples include shear calibration, source photo-z, intrinsic alignment, lens bias, baryonic feedback, and survey mask.","S8 combines sigma8 and Omega_m along a posterior degeneracy direction; many pairs map to the same S8."],
        [f"D(0)=1.00000, D(0.5)={results['growth']['0.5']:.5f}, D(1)={results['growth']['1.0']:.5f}; normalized at z=0; radiation/neutrinos and nonlinear scale effects omitted.",f"At z=0.5, centered estimates are f={results['growth_rate_z0_5_h001']:.6f} for h=0.01 and f={results['growth_rate_z0_5_h0005']:.6f} for h=0.005; compare their absolute difference {abs(results['growth_rate_z0_5_h001']-results['growth_rate_z0_5_h0005']):.3g}.","With C=LL^T, solve y=L^-1 r and chi-square=y^T y. Linear solves are more stable and cheaper than explicitly forming C^-1.","Likelihood contours hold the data model fixed; posterior contours include priors and marginalization. Informative or bounded priors can shift widths or exclude high-likelihood volume."],
        [f"For the 18-row excerpt, beta={results['pantheon_excerpt_gls']['intercept_mag']:.6f} +/- {results['pantheon_excerpt_gls']['intercept_sigma_mag']:.6f} mag; chi-square fixed={results['pantheon_excerpt_gls']['chi2_fixed_intercept']:.4f}, after GLS intercept={results['pantheon_excerpt_gls']['chi2_fitted_intercept']:.4f}.","The excerpt is deliberately stratified, only 18 rows, lacks the full 1701x1701 survey likelihood and selection model; intercept was fit at fixed shape and is not Omega_m/H0 inference.","Read exact fields from the selected published summary row; use reference-log.md for source key, model label, date, and Level 1 versus Level 2 classification.","Need full source likelihood/data, within-probe covariance, cross-probe covariance/shared calibration, harmonized parameterization and priors, nuisance models, and validated selection functions."],
    ]
    for number, (problem, solutions) in enumerate(zip(sets, solved), 1):
        qhtml="".join(f"<section><h2>Question {k}</h2><p>{esc(q)}</p><p><strong>Work to show:</strong> equations, units, assumptions, and a reproducible computation where requested.</p></section>" for k,q in enumerate(problem["questions"],1))
        body=f"<p><strong>Scope:</strong> {esc(problem['scope'])}. Four questions; submit derivations and code/output where requested.</p><p class='notice'>State units and model assumptions. Keep unrounded values in code and round only in your final communication. Revisions and resubmissions are encouraged.</p>{qhtml}<p class='meta'>ASTR 476 · Problem Set {number:02d} · {TODAY}</p>"
        (ROOT/"problem-sets"/f"problem-set-{number:02d}.html").write_text(page(f"Problem Set {number:02d}: {problem['title']}",body),encoding="utf-8")
        sol_html="".join(f"<section><h2>Solution {k}</h2><p>{esc(answer)}</p></section>" for k,answer in enumerate(solutions,1))
        (ROOT/"problem-sets"/f"problem-set-{number:02d}-solutions.html").write_text(page(f"Problem Set {number:02d} Solutions: {problem['title']}",f"<p>Instructor key. Numeric values are generated by <code>build_astr476_package.py</code> from the computation module and the included source subset.</p>{sol_html}"),encoding="utf-8")
        (ROOT/"problem-sets"/f"problem-set-{number:02d}-assessment.md").write_text(
            f"# ASTR 476 Problem Set {number:02d}: Assessment Instructions\n\n"
            f"Scope: {problem['scope']} — {problem['title']}\n\n"
            "Grade for scientific reasoning, dimensional correctness, evidence use, and reproducibility. Do not award full credit for a correct number without its method and assumptions.\n\n"
            "## Rubric (100 points)\n\n- Physical model and derivation: 25\n- Numerical execution and units: 25\n- Uncertainty, covariance, and limitations: 25\n- Interpretation and communication: 15\n- Reproducibility and source attribution: 10\n\n"
            "## Grading protocol\n\nFor each question, identify the claimed quantity, verify equations and unit conversion, independently recompute at least one numerical result, and distinguish measured inputs from derived/model quantities. Apply consequential-error deductions once at the point of propagation rather than repeatedly. Accept equivalent correct methods when assumptions are explicit. Return question-specific feedback and invite a corrected resubmission; the original reasoning standard remains unchanged.\n",
            encoding="utf-8")


