def build_index() -> None:
    template=(REPO_ROOT/"templates"/"course-materials"/"course-index.template.html").read_text(encoding="utf-8")
    manifest=json.loads((ROOT/"course-manifest.json").read_text(encoding="utf-8")); course=manifest["course"]
    replacements={"{{COURSE_CODE}}":CODE,"{{COURSE_TITLE}}":TITLE,"{{CREDITS}}":"3","{{TERM_OR_SEQUENCE}}":"Year 4 elective","{{PACKAGE_STATUS}}":f"{manifest['status']['stage']} · {manifest['status']['reviewStatus']}","{{COURSE_DESCRIPTION}}":course["description"],"{{LAST_UPDATED}}":TODAY,"{{SYLLABUS_STATUS}}":"Fourteen-week syllabus; paired-module assessment cadence documented.","{{SCHEDULE_STATUS}}":"Fourteen weekly modules and seven paired labs/problem sets.","{{REFERENCE_LOG_STATUS}}":"Per-source provenance, exact release hashes, and retrieval limitations recorded.","{{LECTURE_01_TITLE}}":LECTURES[0]["title"],"{{LECTURE_01_STATUS}}":"Slides and notes generated","{{LAB_01_STATUS}}":"Procedure, uncertainty, deliverables, and rubric included","{{PROBLEM_SET_01_STATUS}}":"Assignment, computed solution, and grading protocol included"}
    for key,value in replacements.items(): template=template.replace(key,value)
    report=(ROOT/"review-report.md")
    template=template.replace("{{REVIEW_REPORT_LINK}}",'<p class="meta">Review report: <a href="review-report.md">review-report.md</a></p>' if report.exists() else '<p class="meta">Review report: pending independent review.</p>')
    def section_list(doc: str, heading: str, items: list[str]) -> str:
        pattern=rf"(<h2>{re.escape(heading)}</h2>.*?<ul>).*?(</ul>)"
        out,count=re.subn(pattern,lambda m:m.group(1)+"\n"+"\n".join(items)+m.group(2),doc,count=1,flags=re.DOTALL)
        if count!=1: raise ValueError(f"Unable to fill index section: {heading}")
        return out
    lectures=[f'<li><a href="lectures/lecture-{n:02d}-slides.html">Lecture {n:02d}: {esc(x["title"])} &mdash; slides</a> · <a href="lectures/lecture-{n:02d}-notes.html">Lecture {n:02d}: {esc(x["title"])} &mdash; notes</a></li>' for n,x in enumerate(LECTURES,1)]
    labs=[f'<li><a href="labs/lab-{n:02d}.html">Lab {n:02d}: {esc(x[0])}</a></li>' for n,x in enumerate(LABS,1)]
    psets=[f'<li><a href="problem-sets/problem-set-{n:02d}.html">Problem Set {n:02d}: {esc(x["title"])}</a> · <a href="problem-sets/problem-set-{n:02d}-solutions.html">solutions</a> · <a href="problem-sets/problem-set-{n:02d}-assessment.md">assessment instructions</a></li>' for n,x in enumerate(question_sets({}),1)]
    template=section_list(template,"Lecture Materials",lectures); template=section_list(template,"Labs and Observing",labs); template=section_list(template,"Problem Sets",psets)
    if "{{" in template: raise ValueError("Course index contains an unfilled template token")
    (ROOT/"index.html").write_text(template,encoding="utf-8")


def build_all() -> dict[str, object]:
    if not SUBSET.exists() or not SUBSET_COV.exists():
        raise FileNotFoundError("Run prepare_pantheon_excerpt.py before building ASTR476")
    from astr476_computations import compute_reference_results, self_test
    numeric={**compute_reference_results(),**assessment_results()}
    self_test()
    build_plan(numeric)
    lecture_pages(numeric)
    write_labs(numeric)
    write_problem_sets(numeric)
    build_index()
    return {"lectures":14,"labs":7,"problemSets":7,"pantheonExcerpt":int(numeric["pantheon_excerpt_gls"]["objects"]),"computedInterceptMag":numeric["pantheon_excerpt_gls"]["intercept_mag"]}


if __name__ == "__main__":
    print(json.dumps(build_all(),indent=2,sort_keys=True))